-- ============================================================================
-- Danh mục đơn vị hành chính CẤP XÃ + địa chỉ có cấu trúc (14/09/2026)
-- ============================================================================
--
-- Từ 01/07/2025 Việt Nam chạy mô hình hành chính HAI CẤP: tỉnh/thành → xã/phường/đặc khu.
-- Cấp huyện/quận đã bỏ. Migration này bổ sung nửa còn thiếu của danh mục (bảng `provinces` đã
-- có từ baseline) và đổi mọi ô ĐỊA CHỈ VẬT LÝ từ chuỗi tự do sang cấu trúc:
--     (mã tỉnh, mã xã, phần chi tiết tự gõ, toạ độ + placeId, chuỗi hiển thị đã ghép).
--
-- ⚠️ FK TỔ HỢP viết tay ở cuối file — `(ward_code, province_code) → wards(code, province_code)`
--    trên `booking_requests`, `bookings` và `tenant_customers`. `schema.prisma` KHÔNG mô tả
--    được ba quan hệ tổ hợp tới cùng một model trong một bảng, nên `prisma migrate dev` sẽ sinh
--    lệnh DROP chúng ở migration kế tiếp — GIỮ LẠI như đã làm với các FK `(id, tenant_id)` của
--    baseline. Chúng là thứ khiến "xã phải thuộc tỉnh đã chọn" thành bất biến của DB thay vì
--    một câu if mà mọi service phải nhớ viết. Cùng số phận: các CHECK constraint và index
--    PARTIAL ở file này — Prisma không mô tả được chúng, đừng để migrate dev dọn đi.
--
-- ⚠️ KHÔNG backfill mã xã cho dữ liệu cũ. Địa chỉ tự do cũ chứa tên đơn vị hành chính TRƯỚC
--    sắp xếp; một tên cũ có thể đã bị chia vào nhiều đơn vị mới ("một phần diện tích tự nhiên
--    của..."), nên suy ra mã từ chuỗi chữ là đoán chứ không phải chuyển đổi. Bản ghi cũ giữ
--    NGUYÊN chuỗi hiển thị và toạ độ đang có, được đánh dấu chờ chủ sở hữu xác nhận.

-- ─── Danh mục cấp xã ────────────────────────────────────────────────────────

CREATE TABLE "wards" (
    "code" CHAR(5) NOT NULL,
    "province_code" CHAR(2) NOT NULL,
    "name" VARCHAR(150) NOT NULL,
    "short_name" VARCHAR(150) NOT NULL,
    "administrative_type" VARCHAR(20) NOT NULL,
    "normalized_name" VARCHAR(200) NOT NULL,
    "is_enabled" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),
    "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),

    CONSTRAINT "wards_pkey" PRIMARY KEY ("code")
);

ALTER TABLE "wards" ADD CONSTRAINT "wards_administrative_type_check"
    CHECK ("administrative_type" IN ('ward', 'commune', 'special_zone'));

ALTER TABLE "wards" ADD CONSTRAINT "wards_province_code_fkey"
    FOREIGN KEY ("province_code") REFERENCES "provinces"("code") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Đích của mọi FK tổ hợp bên dưới: một cặp (mã xã, mã tỉnh) chỉ hợp lệ khi xã THẬT SỰ thuộc tỉnh.
CREATE UNIQUE INDEX "wards_code_province_code_key" ON "wards"("code", "province_code");
CREATE INDEX "wards_province_code_name_idx" ON "wards"("province_code", "name");
-- Ô tìm "ba dinh" chạy prefix/ILIKE trên khoá đã bỏ dấu, trong phạm vi MỘT tỉnh.
CREATE INDEX "wards_province_code_normalized_name_idx" ON "wards"("province_code", "normalized_name");
-- 3321 đơn vị hành chính cấp xã (xã/phường/đặc khu).
-- Nguồn: Bộ Nông nghiệp và Môi trường — NXB Tài nguyên Môi trường và Bản đồ Việt Nam (sapnhap.bando.com.vn)
--        https://sapnhap.bando.com.vn/p.co_dvhc — tải ngày 2026-09-14
-- Căn cứ: Quyết định 19/2025/QĐ-TTg (ban hành 30/06/2025, hiệu lực 01/07/2025)
-- Sinh bằng prisma/scripts/gen-ward-sql.ts từ prisma/data/ward-catalog.json — KHÔNG sửa tay.
-- ON CONFLICT: chạy lại KHÔNG nhân bản và KHÔNG đè cờ `is_enabled` admin đã đổi.

