-- ─── Chi nhánh: địa chỉ có cấu trúc ─────────────────────────────────────────

ALTER TABLE "tenant_branches"
    ADD COLUMN "ward_code" CHAR(5),
    ADD COLUMN "address_line" VARCHAR(255),
    ADD COLUMN "place_id" VARCHAR(255),
    ADD COLUMN "location_source" VARCHAR(20);

ALTER TABLE "tenant_branches" ADD CONSTRAINT "tenant_branches_location_source_check"
    CHECK ("location_source" IS NULL
           OR "location_source" IN ('google_place', 'map_pin', 'geocoded', 'manual'));

-- Xã chỉ gắn được khi ĐÃ có tỉnh, và phải thuộc đúng tỉnh đó. Hai vế do DB giữ.
ALTER TABLE "tenant_branches" ADD CONSTRAINT "tenant_branches_ward_needs_province_check"
    CHECK ("ward_code" IS NULL OR "province_code" IS NOT NULL);

ALTER TABLE "tenant_branches" ADD CONSTRAINT "tenant_branches_ward_fkey"
    FOREIGN KEY ("ward_code", "province_code") REFERENCES "wards"("code", "province_code")
    ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE INDEX "tenant_branches_ward_code_idx" ON "tenant_branches"("ward_code");

/*
 * Mọi chi nhánh đang có đều thiếu mã xã — bảng `wards` vừa mới ra đời. Bật cờ chờ xác nhận cho
 * TẤT CẢ (không chỉ những chi nhánh thiếu tỉnh như trước), vì việc cần làm là như nhau: mở form,
 * chọn lại địa chỉ theo danh mục hiện hành, xác nhận ghim.
 *
 * KHÔNG đụng `address`, `latitude`, `longitude`: dữ liệu đang có vẫn là dữ liệu đúng nhất hệ
 * thống biết, và marketplace vẫn phải hiển thị/tính phí bình thường trong lúc chờ.
 */
UPDATE "tenant_branches" SET "needs_location_review" = true WHERE "deleted_at" IS NULL;

-- ─── Hồ sơ gian hàng: mirror hiển thị của chi nhánh mặc định ─────────────────

ALTER TABLE "tenant_profiles"
    ADD COLUMN "ward_code" VARCHAR(10),
    ADD COLUMN "ward_name" VARCHAR(150);

-- ─── Yêu cầu thuê: địa chỉ đón, điểm đến, địa chỉ giao xe ───────────────────

ALTER TABLE "booking_requests"
    ADD COLUMN "pickup_address_line" VARCHAR(255),
    ADD COLUMN "pickup_province_code" CHAR(2),
    ADD COLUMN "pickup_ward_code" CHAR(5),
    ADD COLUMN "pickup_place_id" VARCHAR(255),
    ADD COLUMN "pickup_latitude" DECIMAL(10,7),
    ADD COLUMN "pickup_longitude" DECIMAL(10,7),
    ADD COLUMN "destination_place_id" VARCHAR(255),
    ADD COLUMN "destination_latitude" DECIMAL(10,7),
    ADD COLUMN "destination_longitude" DECIMAL(10,7),
    ADD COLUMN "delivery_address_line" VARCHAR(255),
    ADD COLUMN "delivery_province_code" CHAR(2),
    ADD COLUMN "delivery_ward_code" CHAR(5),
    ADD COLUMN "delivery_place_id" VARCHAR(255),
    ADD COLUMN "delivery_latitude" DECIMAL(10,7),
    ADD COLUMN "delivery_longitude" DECIMAL(10,7);

ALTER TABLE "booking_requests" ADD CONSTRAINT "booking_requests_pickup_ward_fkey"
    FOREIGN KEY ("pickup_ward_code", "pickup_province_code") REFERENCES "wards"("code", "province_code")
    ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "booking_requests" ADD CONSTRAINT "booking_requests_delivery_ward_fkey"
    FOREIGN KEY ("delivery_ward_code", "delivery_province_code") REFERENCES "wards"("code", "province_code")
    ON DELETE RESTRICT ON UPDATE CASCADE;

-- Lọc "yêu cầu giao xe về tỉnh nào" — chỉ trên dòng CÓ địa chỉ giao, nên index partial.
CREATE INDEX "booking_requests_delivery_province_idx"
    ON "booking_requests"("delivery_province_code") WHERE "delivery_province_code" IS NOT NULL;

-- ─── Đơn thuê: snapshot địa chỉ đón + điểm đến ──────────────────────────────

ALTER TABLE "bookings"
    ADD COLUMN "pickup_address_line" VARCHAR(255),
    ADD COLUMN "pickup_province_code" CHAR(2),
    ADD COLUMN "pickup_ward_code" CHAR(5),
    ADD COLUMN "pickup_place_id" VARCHAR(255),
    ADD COLUMN "pickup_latitude" DECIMAL(10,7),
    ADD COLUMN "pickup_longitude" DECIMAL(10,7),
    ADD COLUMN "destination_place_id" VARCHAR(255),
    ADD COLUMN "destination_latitude" DECIMAL(10,7),
    ADD COLUMN "destination_longitude" DECIMAL(10,7);

ALTER TABLE "bookings" ADD CONSTRAINT "bookings_pickup_ward_fkey"
    FOREIGN KEY ("pickup_ward_code", "pickup_province_code") REFERENCES "wards"("code", "province_code")
    ON DELETE RESTRICT ON UPDATE CASCADE;

-- ─── Sổ khách của gian hàng ─────────────────────────────────────────────────

ALTER TABLE "tenant_customers"
    ADD COLUMN "address_line" VARCHAR(255),
    ADD COLUMN "province_code" CHAR(2),
    ADD COLUMN "ward_code" CHAR(5);

ALTER TABLE "tenant_customers" ADD CONSTRAINT "tenant_customers_ward_fkey"
    FOREIGN KEY ("ward_code", "province_code") REFERENCES "wards"("code", "province_code")
    ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE INDEX "tenant_customers_tenant_id_province_code_idx"
    ON "tenant_customers"("tenant_id", "province_code");

-- ─── Thứ tự hiển thị của bộ chọn tỉnh ───────────────────────────────────────
--
-- Sáu thành phố trực thuộc trung ương lên đầu, rồi 28 tỉnh theo bảng chữ cái. Thứ tự cũ là
-- thứ tự MÃ HÀNH CHÍNH, nên "Cao Bằng" đứng thứ hai còn "Hồ Chí Minh" nằm giữa danh sách —
-- người dùng phải cuộn qua 27 dòng để tới thứ họ chọn nhiều nhất.
--
-- Chỉ đụng `sort_order`: tên, mã và hai cờ hiển thị giữ nguyên. Admin vẫn sửa lại được.
UPDATE "provinces" AS p SET "sort_order" = v."sort_order", "updated_at" = now()
FROM (VALUES
  ('01', 1),
  ('79', 2),
  ('48', 3),
  ('31', 4),
  ('92', 5),
  ('46', 6),
  ('91', 7),
  ('24', 8),
  ('96', 9),
  ('04', 10),
  ('66', 11),
  ('11', 12),
  ('75', 13),
  ('82', 14),
  ('52', 15),
  ('42', 16),
  ('33', 17),
  ('56', 18),
  ('12', 19),
  ('20', 20),
  ('15', 21),
  ('68', 22),
  ('40', 23),
  ('37', 24),
  ('25', 25),
  ('51', 26),
  ('22', 27),
  ('44', 28),
  ('14', 29),
  ('80', 30),
  ('19', 31),
  ('38', 32),
  ('08', 33),
  ('86', 34)
) AS v("code", "sort_order")
WHERE p."code" = v."code" AND p."sort_order" IS DISTINCT FROM v."sort_order";
